    @Nullable
    public final SQLQueryComplexName referenceName;
    @NotNull
    public final SQLQueryRowsSourceModel source;
    @Nullable
    public final DBSEntity tableOrNull;
    @Nullable
    public final SQLQuerySymbol aliasOrNull;
