178	    /**
179	     * Find semantic model item responsible for the representation of the data rows source having a given name
180	     * (table reference, named subquery, etc)
181	     *
182	     * @implNote TODO consider ambiguous table names
183	     */
184	    @Nullable
185	    public SourceResolutionInfo findReferencedSource(@NotNull SQLQueryComplexName name) {
186	        if (!name.parts.isEmpty()) {
187	            SQLQuerySymbolEntry entry = name.parts.getFirst();
188	            SourceResolutionResult result = this.findSourceByAlias(entry.getName());
189	            if (result != null) {
190	                SQLQueryMemberAccessEntry endingPeriod;
191	                if (name.parts.size() > 1 && name.parts.get(1) != null) {
192	                    endingPeriod = name.parts.get(1).getMemberAccess();
193	                } else if (name.parts.size() == 2 && name.parts.get(1) == null) {
194	                    endingPeriod = name.endingPeriodNode;
195	                } else {
196	                    endingPeriod = null;
197	                }
198	                SQLQueryComplexName key = new SQLQueryComplexName(entry.getSyntaxNode(), List.of(entry), 0, endingPeriod);
199	                return new SourceResolutionInfo(result, key);
200	            }
201	        }
202	
203	        SQLQueryComplexName namePart = name;
204	        while (namePart != null) {
205	            SourceResolutionResult result = this.rowsSources.get(namePart);
206	            if (result != null) {
207	                return new SourceResolutionInfo(result, namePart);
208	            } else {
209	                namePart = namePart.trimEnd();
210	            }
211	        }
212	        return null;
213	    }
