256	    /**
257	     * Prepare new semantic context by introducing rows source
258	     */
259	    @NotNull
260	    public final SQLQueryRowsSourceContext appendSource(
261	        @NotNull SQLQueryRowsSourceModel source,
262	        @NotNull SQLQueryComplexName classifiedName,
263	        @Nullable DBSEntity tableOrNull
264	    ) {
265	        SourceResolutionResult srr = new SourceResolutionResult(source, classifiedName, tableOrNull, null);
266	
267	        ArrayList<Map.Entry<SQLQueryComplexName, SourceResolutionResult>> newSourceEntries = new ArrayList<>(5);
268	        addSourceEntryVariants(newSourceEntries, classifiedName, srr);
269	
270	        if (tableOrNull != null && classifiedName.parts.getFirst().getDefinition() instanceof SQLQuerySymbolByDbObjectDefinition subparent) {
271	            addParentObjectVariants(newSourceEntries, classifiedName, srr, subparent.getDbObject());
272	        }
273	
274	        return this.fork(
275	            this.hasUnresolvedSource,
276	            this.rowsSources.put(newSourceEntries),
277	            this.dynamicTableSources,
278	            this.sourcesByLoweredAlias,
279	            this.relatedContextProvider
280	        );
281	    }
