283	    /**
284	     * Associate alias with the resolved query source
285	     */
286	    @NotNull
287	    public final SQLQueryRowsSourceContext replaceWithAlias(
288	        @NotNull SQLQueryRowsSourceModel oldSource,
289	        @NotNull SQLQueryRowsSourceModel newSource,
290	        @NotNull SQLQuerySymbolEntry alias
291	    ) {
292	        List<Map.Entry<SQLQueryComplexName, SourceResolutionResult>> oldEntries = this.rowsSources.entrySet().stream()
293	            .filter(s -> s.getValue().source == oldSource).toList();
294	
295	        DBSEntity oldEntryTable = oldEntries.isEmpty() ? null : oldEntries.getFirst().getValue().tableOrNull;
296	        SourceResolutionResult newEntry = new SourceResolutionResult(newSource, null, oldEntryTable, alias.getSymbol());
297	
298	        return this.fork(
299	            this.hasUnresolvedSource,
300	            this.rowsSources.remove(oldEntries),
301	            this.dynamicTableSources,
302	            this.sourcesByLoweredAlias.put(alias.getName().toLowerCase(), newEntry),
303	            this.relatedContextProvider
304	        );
305	    }
