308	     * Prepare new semantic context by introducing rows source
309	     */
310	    @NotNull
311	    public final SQLQueryRowsSourceContext appendCteSources(@NotNull List<Pair<SQLQuerySymbolEntry, SQLQueryRowsSourceModel>> sources) {
312	        ArrayList<Map.Entry<String, SourceResolutionResult>> newSourceEntries = new ArrayList<>(sources.size());
313	        for (Pair<SQLQuerySymbolEntry, ? extends SQLQueryRowsSourceModel> entry : sources) {
314	            SQLQuerySymbolEntry alias = entry.getFirst();
315	            if (alias != null) {
316	                SQLQueryRowsSourceModel sourceModel = entry.getSecond();
317	                SQLQueryComplexName name = new SQLQueryComplexName(alias.getSyntaxNode(), List.of(alias), 0, null);
318	                newSourceEntries.add(Map.entry(
319	                    alias.getName().toLowerCase(),
320	                    new SourceResolutionResult(sourceModel, name, null, alias.getSymbol())
321	                ));
322	            }
323	        }
324	        return this.fork(
325	            this.hasUnresolvedSource,
326	            this.rowsSources,
327	            this.dynamicTableSources.put(newSourceEntries),
328	            this.sourcesByLoweredAlias,
329	            this.relatedContextProvider
330	        );
331	    }
