435	    @NotNull
436	    private static void addSourceEntryVariants(
437	        @NotNull ArrayList<Map.Entry<SQLQueryComplexName, SourceResolutionResult>> entries,
438	        @NotNull SQLQueryComplexName classifiedName,
439	        @NotNull SourceResolutionResult source
440	    ) {
441	        entries.add(Map.entry(classifiedName, source));
442	        for (SQLQueryComplexName nameFragment = classifiedName.trimStart(); nameFragment != null; nameFragment = nameFragment.trimStart()) {
443	            entries.add(Map.entry(nameFragment, source));
444	        }
445	    }
446	
447	    private void addParentObjectVariants(
448	        @NotNull ArrayList<Map.Entry<SQLQueryComplexName, SourceResolutionResult>> entries,
449	        @NotNull SQLQueryComplexName classifiedName,
450	        @NotNull SourceResolutionResult source,
451	        @NotNull DBSObject parentObject
452	    ) {
453	        SQLQueryComplexName synthesizedName = classifiedName;
454	        for (DBSObject object = parentObject; object != null && !(object instanceof DBPDataSource); object = object.getParentObject()) {
455	            String canonicalName = SQLUtils.identifierToCanonicalForm(this.connectionInfo.dialect, object.getName(), false, true);
456	            SQLQuerySymbolEntry entry = new SQLQuerySymbolEntry(classifiedName.syntaxNode, canonicalName, object.getName(), null);
457	            entry.setDefinition(new SQLQuerySymbolByDbObjectDefinition(object, SQLQuerySemanticUtils.inferSymbolClass(object)));
458	            synthesizedName = synthesizedName.prepend(entry);
459	            entries.add(Map.entry(synthesizedName, source));
460	        }
461	    }
