463	    @NotNull
464	    private Set<SourceResolutionResult> collectSourceResolutions(boolean forQuerySubscope) {
465	        ListNode<SQLQueryRowsSourceContext> queue = ListNode.of(this);
466	        Set<SQLQueryRowsSourceContext> queued = new HashSet<>();
467	        queued.add(this);
468	
469	        Set<SourceResolutionResult> allSourceResolutions = new HashSet<>();
470	
471	        while (queue != null) {
472	            SQLQueryRowsSourceContext source = queue.data;
473	            queue = queue.next;
474	
475	            this.collectSourceResolutions(source, allSourceResolutions);
476	
477	            if (forQuerySubscope) {
478	                for (ListNode<SQLQueryRowsSourceContext> item = source.targetRowContexts; item != null; item = item.next) {
479	                    if (queued.add(item.data)) {
480	                        queue = ListNode.push(queue, item.data);
481	                    }
482	                }
483	            }
484	        }
485	
486	        return allSourceResolutions;
487	    }
488	
489	    private void collectSourceResolutions(
490	        @NotNull SQLQueryRowsSourceContext source,
491	        @NotNull Set<SourceResolutionResult> allSourceResolutions
492	    ) {
493	        allSourceResolutions.addAll(source.rowsSources.values());
494	        allSourceResolutions.addAll(source.sourcesByLoweredAlias.values());
495	        allSourceResolutions.addAll(source.dynamicTableSources.values());
496	    }
497	
498	    @NotNull
499	    private SQLQuerySourcesInfoCollection buildKnownSourcesCollection(@NotNull Set<SourceResolutionResult> allSourceResolutions) {
500	        Map<SQLQueryRowsSourceModel, SourceResolutionResult> resolutionResults = allSourceResolutions.stream()
501	            .collect(Collectors.toMap(s -> s.source, Function.identity()));
502	        Set<DBSEntity> referencedTables = allSourceResolutions.stream()
503	            .map(s -> s.tableOrNull)
504	            .filter(Objects::nonNull)
505	            .collect(Collectors.toSet());
506	        Set<String> aliasesInUse = allSourceResolutions.stream()
507	            .map(s -> s.aliasOrNull)
508	            .filter(Objects::nonNull)
509	            .map(SQLQuerySymbol::getName)
510	            .map(String::toLowerCase)
511	            .collect(Collectors.toSet());
512	
513	        return new SQLQuerySourcesInfoCollection() {
514	            @NotNull
515	            @Override
516	            public Map<SQLQueryRowsSourceModel, SourceResolutionResult> getResolutionResults() {
517	                return resolutionResults;
518	            }
519	
520	            @NotNull
521	            @Override
522	            public Set<DBSEntity> getReferencedTables() {
523	                return referencedTables;
524	            }
525	
526	            @NotNull
527	            @Override
528	            public Set<String> getAliasesInUse() {
529	                return aliasesInUse;
530	            }
531	        };
532	    }
